<script lang="ts">
 import { filterRowsByTag, sortRows, eventTypeCounts, filterEventsByType, deriveHandEntries } from './record-tools';
 import { eventTypeLabels } from './event-type-labels'
 import { getLiveStatusLabel, getMatchStatusLabel } from './session-labels';
 export let meeting:any=null; export let record:any={}; export let state:any={}; export let events:any[]=[]; export let users:any[]=[]; export let language='en'; export let live=false; export let onCaptureManual:()=>void=()=>{}; export let onCaptureHands:()=>void=()=>{};
 interface $$Slots { matching: {} }
 let tab='overview', tag='', search='', sort='name', direction:'asc'|'desc'='asc', typeFilter='', timeNewest=true, displayMode='generic';
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 const dateTime=(value:string|number|Date)=>new Intl.DateTimeFormat(language==='zh-CN'?'zh-CN':'en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
 const timeOnly=(value:string|number|Date)=>new Intl.DateTimeFormat(language==='zh-CN'?'zh-CN':'en',{hour:'numeric',minute:'2-digit'}).format(new Date(value));
 const eventLabel=(type:string)=>{const label=(eventTypeLabels as any)[type];return label?t(label.zh,label.en):type};
 $: if(record.mode) displayMode=record.mode;
 $: movement=record.record?.movementEvents||record.movementEvents||[];
 $: names=record.record?.nameChangeEvents||record.nameChangeEvents||[];
 $: handEntries=deriveHandEntries(events,users);
 $: raised=users.filter((u:any)=>u.raisedHand||u.raised_hand);
 $: entryCounts=eventTypeCounts(movement);
 $: filtered=sortRows(filterRowsByTag(record.rows||[],tag).filter((r:any)=>!search||`${r.canonicalName||''} ${r.zoomName||''} ${(r.zoomNames||[]).join(' ')} ${r.pinyin||''}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())),sort,direction);
 $: filteredMovement=filterEventsByType(movement,typeFilter).filter((e:any)=>!search||`${e.participant?.screenName||''} ${e.participant?.screenNamePinyin||''}`.toLowerCase().includes(search.toLowerCase())).sort((a:any,b:any)=>(Date.parse(a.timestamp)-Date.parse(b.timestamp))*(timeNewest?-1:1));
 const tabs=[['overview','Overview','概览'],['attendance','Auto Attendance','自动考勤'],['matching','Name Matching','昵称匹配'],['settings','Attendance Settings','考勤配置'],['names','Name Changes','名称变更'],['entry','Entry/Exit','进出记录'],['hands','Raise Hand','举手跟踪'],['manual','Manual Attendance Records','手动考勤']];
 const attendanceLabels:Record<string,string>={seen:'到过',full_present:'全程',late:'迟到',returned:'返回',left_early:'早退',missing:'缺席',ignored:'不计入',total:'总计'};
 const movementTypes=[['joinedBefore','Already in meeting at startup','启动时已加入'],['join','Joined meeting','进入会议'],['leave','Left meeting','离开会议'],['waitingRoomJoinFromOutside','Entered waiting room','进入等候室'],['waitingRoomJoinFromMeeting','Moved to waiting room','被移到等候室'],['waitingRoomJoinedBefore','In waiting room at startup','启动时已在等候室'],['waitingRoomLeave','Left waiting room','离开等候室']];
 $: visibleTabs=tabs.filter(([key])=>key!=='hands'||live||handEntries.length||state.raiseHandCaptures?.length);
</script>
<section class="record-activity">
 <nav class="activity-tabs">{#each visibleTabs as [key,en,zh]}<button class:chosen={tab===key} onclick={()=>{tab=key;search='';tag='';typeFilter=''}}>{t(zh,en)}{#if (key==='names'&&names.length)||(key==='entry'&&movement.length)||(key==='manual'&&state.manualSnapshots?.length)}<small class="tab-count">{key==='names'?names.length:key==='entry'?movement.length:state.manualSnapshots.length}</small>{/if}</button>{/each}</nav>
 {#if tab==='overview'}
 <div class="activity-cards">{#each [[t('会议编号','Meeting number'),meeting?.meetingNumber||'—'],[t('开始时间','Started'),meeting?.startedAt?dateTime(meeting.startedAt):'—'],[t('结束时间','Ended'),meeting?.endedAt?dateTime(meeting.endedAt):t('进行中','In progress')],[t('持续时间','Duration'),`${Math.floor((record.durationMinutes||0)/60)}:${String(Math.round(record.durationMinutes||0)%60).padStart(2,'0')}`],[t('使用配置','Profile used'),record.record?.selectedProfileId||'—'],[t('来源','Source'),meeting?.source==='imported'?t('导入','Imported'):t('实时','Live')],[t('导出状态','Export status'),state.exportedAt?t('已下载','Downloaded'):t('未下载','Not downloaded')],[t('手动记录','Manual records'),state.manualSnapshots?.length||0],[t('决定数','Decisions'),state.reconciliationDecisions?.length||0],[t('进出事件','Entry/exit events'),movement.length],[t('未匹配','Unmatched'),(record.rows||[]).filter((r:any)=>r.matchStatus==='unmatched').length],[t('访客','Guests'),(record.rows||[]).filter((r:any)=>r.matchStatus==='guest').length]] as card}<article><small>{card[0]}</small><b>{card[1]}</b></article>{/each}</div>
 {#if live}<button onclick={onCaptureManual}>{t('捕获当前列表','Capture current list')}</button>{/if}
 {:else if tab==='attendance'}
 <div class="activity-toolbar">{#each [['seen','Seen'],['full_present','Full Present'],['late','Late'],['returned','Returned'],['left_early','Left Early'],['missing','Absent'],['ignored','Ignored'],['total','All']] as [key,label]}<button class:chosen={tag===key} onclick={()=>tag=tag===key?'':key}>{t(attendanceLabels[key],label)} · {filterRowsByTag(record.rows||[],key).length}</button>{/each}<input aria-label={t('搜索姓名、拼音或 Zoom 名称','Search names, pinyin or Zoom names')} placeholder={t('搜索姓名、拼音或 Zoom 名称','Search names, pinyin or Zoom names')} bind:value={search}/><select bind:value={sort}><option value="name">{t('姓名','Name')}</option><option value="score">{t('分数','Score')}</option><option value="firstJoin">{t('首次加入','First join')}</option><option value="minutes">{t('分钟','Minutes')}</option></select><button onclick={()=>direction=direction==='asc'?'desc':'asc'}>{direction==='asc'?'↑':'↓'}</button></div>
 <div class="activity-toolbar"><button class:chosen={displayMode!=='roster'} onclick={()=>displayMode='generic'}>{t('通用','Generic')}</button><button class:chosen={displayMode==='roster'} onclick={()=>displayMode='roster'}>{t('花名册','Roster')}</button></div>
 <div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('Zoom 名称','Zoom name')}</th><th>{t('状态','Status')}</th><th>{t('标签 / 小组','Tags / Group')}</th><th>{t('分数','Score')}</th><th>{t('首次加入','First join')}</th><th>{t('分钟','Minutes')}</th></tr></thead><tbody>{#each filtered.filter((r:any)=>displayMode==='roster'||r.currentStatus!=='missing') as r}<tr><td>{r.canonicalName||r.zoomName}</td><td>{r.zoomNames?.join(', ')||r.zoomName}</td><td>{getLiveStatusLabel(r.currentStatus,language as any)}</td><td>{#each r.tags||[] as chip}<span class="chip">{chip}</span>{/each} {#if r.group}<span class="chip">{r.group}</span>{/if}</td><td><span class="score">{Math.round(r.score||0)}% · {Number(r.score)>=90?t('优秀','Excellent'):Number(r.score)>=75?t('良好','Good'):Number(r.score)>=50?t('一般','Moderate'):Number(r.score)>0?t('较差','Poor'):t('缺席','Absent')}</span></td><td>{r.firstJoinAt?timeOnly(r.firstJoinAt):'—'}</td><td>{Math.round(r.totalPresenceMinutes||0)}</td></tr>{/each}</tbody></table></div>
 {:else if tab==='matching'}<slot name="matching"/>
 {:else if tab==='settings'}<div class="activity-cards">{#each [[t('迟到阈值','Late threshold'),`${record.record?.lateAfterMinutes??'—'} ${t('分钟','min')}`],[t('返回窗口','Return window'),`${record.record?.returnWindowMinutes??'—'} ${t('分钟','min')}`],[t('选择的配置','Selected profile'),record.record?.selectedProfileId||'—'],[t('包含的小组','Included groups'),(record.record?.selectedIncludedSubgroups||[]).join(', ')||t('全部','All')]] as item}<article><small>{item[0]}</small><b>{item[1]}</b></article>{/each}</div>
 {:else if tab==='names'}<h3>{t('名称变更','Name Changes')}{#if names.length} · {names.length}{/if}</h3>{#each [...names].reverse() as n}<article class="event-row"><time>{dateTime(n.timestamp)}</time><b>{n.previousScreenName||n.previous_screen_name} → {n.nextScreenName||n.next_screen_name}</b></article>{:else}<p>{t('没有名称变更','No name changes')}</p>{/each}
 {:else if tab==='entry'}<div class="activity-toolbar"><input placeholder={t('搜索名称','Search names')} bind:value={search}/>{#each movementTypes as [type,en,zh]}<button class:chosen={typeFilter===type} onclick={()=>typeFilter=typeFilter===type?'':type}>{t(zh,en)} · {entryCounts[type]||0}</button>{/each}<button onclick={()=>timeNewest=!timeNewest}>{timeNewest?t('最新优先','Newest first'):t('最早优先','Oldest first')}</button></div>{#each filteredMovement as e}<article class="event-row"><time>{dateTime(e.timestamp)}</time><b>{e.participant?.screenName||'—'}</b><span>{eventLabel(e.type)}</span></article>{:else}<p>{t('没有进出事件','No entry or exit events')}</p>{/each}
 {:else if tab==='hands'}<div class="activity-toolbar"><input placeholder={t('搜索举手记录','Search raise-hand records')} bind:value={search}/><button disabled={!raised.length} onclick={onCaptureHands}>{t('捕获举手记录','Capture raise-hand records')}</button></div><h3>{t('当前举手','Currently raised')} · {raised.length}</h3>{#each raised as u}<span class="chip">{u.name}</span>{/each}<h3>{t('举手事件','Raise/lower event log')}</h3>{#each handEntries.filter((e:any)=>!search||e.screenName.toLowerCase().includes(search.toLowerCase())).slice().reverse() as e}<article class="event-row"><time>{dateTime(e.timestamp)}</time><b>{e.screenName}</b><span>{e.action==='raise'?t('举手','Raised hand'):t('放下手','Lowered hand')}</span></article>{/each}<h3>{t('举手记录快照','Raise-hand captures')}</h3>{#each state.raiseHandCaptures||[] as c}<article>{dateTime(c.timestamp)} · {c.totalCount} · {c.screenNames?.join(', ')}</article>{/each}
 {:else}<div class="activity-toolbar"><button onclick={onCaptureManual}>{t('捕获当前列表','Capture current list')}</button></div>{#each [...(state.manualSnapshots||[])].reverse() as s,i}<details open={i===0}><summary>{dateTime(s.timestamp)} · {s.participants?.length||0}</summary><div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('位置','Location')}</th><th>{t('匹配','Match')}</th></tr></thead><tbody>{#each s.participants||[] as p}<tr><td>{p.screenName}</td><td>{p.location==='meeting'?t('会议中','Meeting'):p.location==='waiting-room'?t('等候室','Waiting Room'):p.location}</td><td>{p.matchedCanonicalName||getMatchStatusLabel(p.matchStatus,language as any)}</td></tr>{/each}</tbody></table></div></details>{:else}<p>{t('尚无手动考勤记录','No manual attendance records yet')}</p>{/each}{/if}
</section>
<style>
 .record-activity{margin-top:16px;min-width:0}.activity-tabs,.activity-toolbar,.activity-cards{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.activity-tabs{border-bottom:1px solid var(--line);flex-wrap:nowrap;overflow-x:auto;scrollbar-width:thin}.activity-tabs button{flex:0 0 auto}.activity-tabs button{background:transparent;border:0;padding:10px 12px;cursor:pointer;display:inline-flex;align-items:center;gap:8px;white-space:nowrap}.activity-tabs button.chosen{color:var(--accent);border-bottom:2px solid var(--accent)}.tab-count{font-size:10px;line-height:18px;min-width:19px;text-align:center;background:#eef2f7;color:#697586;border-radius:12px;padding:0 6px}.activity-toolbar{align-items:center}.activity-toolbar input{flex:1;min-width:160px}.activity-toolbar input,.activity-toolbar select{padding:8px;border:1px solid var(--line-strong);border-radius:7px}.activity-cards article{flex:1 1 145px;min-width:0;display:grid;gap:6px;border:1px solid var(--line);border-radius:9px;padding:12px}.activity-cards small,.event-row time{color:var(--muted)}.event-row{display:flex;gap:14px;align-items:center;padding:10px;border-bottom:1px solid var(--line)}.event-row time{min-width:150px}.event-row span{margin-left:auto}.score,.chip{background:#edf3ff;padding:3px 7px;border-radius:12px}
</style>
